def naive(X):
    N = len(X)
    for a in permutations(list(range(N))*N):

        for i,x in enumerate(X):
            if not (a[x] == i and sum(v==i for v in a[:x]) == i):
                break
        else:
            return [v+1 for v in a]
    return None

