def diff(p, i):
    return p[(i + 1) % len(p)] - p[i]

# http://www.prefield.com/algorithm/geometry/convex_diameter.html
def convex_diameter(p):
    js = ks = 0
    for i in range(1, len(p)):
        if p[i].imag > p[js].imag:
            js = i
        if p[i].imag < p[ks].imag:
            ks = i

    maxd = abs(p[js] - p[ks])
    j, k = js, ks
    while True:
        if cross(diff(p, j), diff(p, k)) >= 0:
            k = (k + 1) % len(p)
        else:
            j = (j + 1) % len(p)
        if maxd < abs(p[j] - p[k]):
            maxd = abs(p[j] - p[k])
        if j == js and k == ks:
            break
    return maxd


